<?php require_once __DIR__.'/../includes/config.php';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();if($count>0){$message='An administrator already exists. Setup is disabled.';}else{$username=trim($_POST['username']??'');$password=$_POST['password']??'';if(strlen($username)<4||strlen($password)<12){$message='Use a username of at least 4 characters and password of at least 12 characters.';}else{$s=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$s->execute([$username,password_hash($password,PASSWORD_DEFAULT)]);$message='Admin account created. Delete or rename this setup.php file on your server now.';}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin setup | Ladle Loan</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="form-wrap"><form class="form-card" method="post"><h1>One-time admin setup</h1><div class="notice">Create your own admin credentials. No default password is provided.</div><?php if($message):?><div class="notice"><?=e($message)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Username<input name="username" required></label><label>Strong password<input type="password" name="password" minlength="12" required></label><button class="btn">Create admin</button><p><a href="login.php">Admin login</a></p></form></div></body></html>